// @ts-ignore Generated by OpenNext during build.
import handler from "./.open-next/worker.js";
import {cronTick, handleEngine} from "./lib/engine-worker";
import {VIA_HEADER, VIEWER_HEADER, cleanupLogins, handleLogin, isPublicPath, signedIn} from "./lib/login-worker";

// Pages may only load and send to this origin.
// Next's inline bootstrap scripts need 'unsafe-inline'; connect/img/form limits keep data from leaving.
const CSP=[
  "default-src 'self'","script-src 'self' 'unsafe-inline'","style-src 'self' 'unsafe-inline'","img-src 'self' blob: data:",
  "font-src 'self' data:","connect-src 'self'","worker-src 'self'","manifest-src 'self'","media-src 'self' blob:",
  "object-src 'none'","base-uri 'none'","form-action 'self'","frame-ancestors 'none'",
].join("; ");

function secured(response: Response) {
  const out=new Response(response.body,response);
  out.headers.set("Content-Security-Policy",CSP);
  out.headers.set("X-Content-Type-Options","nosniff");
  out.headers.set("Referrer-Policy","same-origin");
  out.headers.set("Strict-Transport-Security","max-age=31536000");
  return out;
}

export default {
  async fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext): Promise<Response> {
    return secured(await handle(request,env,ctx));
  },
  async scheduled(_event: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    ctx.waitUntil(cleanupLogins(env).catch(()=>console.error("Login cleanup failed")));
    ctx.waitUntil(cronTick(env).catch(()=>console.error("Engine cron failed")));
  },
} satisfies ExportedHandler<CloudflareEnv>;

async function handle(request: Request, env: CloudflareEnv, ctx: ExecutionContext): Promise<Response> {
  // The Mac engine has its own token and never gets a session.
  const engine=await handleEngine(request,env);
  if (engine) return engine;
  const login=await handleLogin(request,env);
  if (login) return login;

  // The only place that decides who is asking; the app trusts this header alone.
  const path=new URL(request.url).pathname;
  const viewer=await signedIn(request,env);
  if (!viewer && !isPublicPath(path)) {
    if (request.method==="GET" && (request.headers.get("Accept") ?? "").includes("text/html"))
      return Response.redirect(new URL(`/login?next=${encodeURIComponent(path)}`, request.url).toString(), 302);
    return new Response("Login required", {status:401});
  }
  const headers=new Headers(request.headers);
  headers.delete(VIEWER_HEADER);
  headers.delete(VIA_HEADER);
  if (viewer) {
    headers.set(VIEWER_HEADER, viewer.email);
    headers.set(VIA_HEADER, viewer.via);
  }
  let response=await handler.fetch(new Request(request,{headers}),env,ctx);
  if (viewer?.refresh) {
    response=new Response(response.body,response);
    response.headers.append("Set-Cookie",viewer.refresh);
  }
  return response;
}
